window.QUIZ_BANK['playwright'] = (window.QUIZ_BANK['playwright']||[]).concat([
{id:4391,topic:'playwright',difficulty:'beginner',question:'Who develops and maintains Playwright?',options:['Google','Microsoft','Meta','JetBrains'],answer:1,explanation:'Playwright is an open-source browser automation library created and actively maintained by Microsoft. It was first released in 2020 and supports Chromium, Firefox, and WebKit browsers.'},
{id:4392,topic:'playwright',difficulty:'beginner',question:'Which browsers does Playwright support out of the box?',options:['Chrome and Firefox only','Chromium, Firefox, and WebKit','Chrome, Edge, and Safari','Firefox, Opera, and Brave'],answer:1,explanation:'Playwright supports three browser engines: Chromium (covers Chrome and Edge), Firefox, and WebKit (covers Safari). This cross-browser coverage is a core design goal of the framework.'},
{id:4393,topic:'playwright',difficulty:'beginner',question:'What command initializes a new Playwright project with all dependencies and example tests?',options:['npm install playwright','npm init playwright@latest','npx playwright init','npm create playwright'],answer:1,explanation:'Running `npm init playwright@latest` scaffolds a new Playwright project. It installs @playwright/test, creates playwright.config.ts, downloads browser binaries, and generates example test files automatically.'},
{id:4394,topic:'playwright',difficulty:'beginner',question:'Which file holds the main configuration for a Playwright test suite?',options:['playwright.json','jest.config.ts','playwright.config.ts','test.setup.ts'],answer:2,explanation:'playwright.config.ts (or playwright.config.js) is the central configuration file for Playwright Test. It defines projects, browser settings, base URL, timeouts, retries, reporters, and more.'},
{id:4395,topic:'playwright',difficulty:'beginner',question:'What is the Playwright equivalent of a browser profile or isolated session?',options:['Page','BrowserContext','Tab','Frame'],answer:1,explanation:'A BrowserContext in Playwright is an isolated browser session similar to an incognito profile. Each context has its own cookies, localStorage, and cache, enabling clean parallel test execution.'},
{id:4396,topic:'playwright',difficulty:'beginner',question:'Which Playwright locator method finds an element by its ARIA role?',options:['page.getByName()','page.getByRole()','page.getByAriaLabel()','page.getByClass()'],answer:1,explanation:'`page.getByRole()` finds elements using ARIA roles such as button, textbox, heading, link, etc. It is the recommended locator strategy as it reflects how users and screen readers interact with the page.'},
{id:4397,topic:'playwright',difficulty:'beginner',question:'What does `page.goto(url)` do in Playwright?',options:['Opens a new browser tab','Navigates the current page to the given URL','Reloads the current page','Waits for the URL to change'],answer:1,explanation:'`page.goto(url)` navigates the Playwright Page object to the specified URL. It returns a Response object and by default waits until the `load` event fires before resolving.'},
{id:4398,topic:'playwright',difficulty:'beginner',question:'Which method fills an input field with text in Playwright?',options:['page.type()','page.setValue()','page.fill()','page.input()'],answer:2,explanation:'`page.fill(selector, value)` or `locator.fill(value)` clears an input and types the provided text. Unlike `type()`, it sets the value in one operation and triggers appropriate input events.'},
{id:4399,topic:'playwright',difficulty:'beginner',question:'What is the default timeout for most Playwright actions and assertions?',options:['5 seconds','30 seconds','60 seconds','10 seconds'],answer:1,explanation:'Playwright default action timeout is 30 seconds. This applies to actions like click, fill, and to assertions via expect(). It can be overridden globally in playwright.config.ts or per-call.'},
{id:4400,topic:'playwright',difficulty:'beginner',question:'How do you take a full-page screenshot in Playwright?',options:["page.screenshot({ fullPage: true })",'page.capture({ mode: "full" })','browser.screenshot()','page.fullScreenshot()'],answer:0,explanation:'`page.screenshot({ fullPage: true })` captures the entire scrollable page, not just the visible viewport. Without the option, only the viewport is captured. The result is a PNG buffer or saved to a file path.'},
{id:4401,topic:'playwright',difficulty:'intermediate',question:'What is a key architectural difference between Playwright and Selenium WebDriver?',options:['Playwright uses HTTP to communicate with browsers','Playwright uses CDP/browser-native protocols for direct browser communication','Selenium supports more browsers than Playwright','Playwright requires a separate driver executable like chromedriver'],answer:1,explanation:'Playwright communicates with browsers using the Chrome DevTools Protocol (CDP) for Chromium, and equivalent native protocols for Firefox and WebKit. Selenium uses the W3C WebDriver HTTP protocol, which adds latency compared to Playwright\'s direct pipe-based communication.'},
{id:4402,topic:'playwright',difficulty:'intermediate',question:'Which configuration key in playwright.config.ts sets a base URL so tests can use relative paths in page.goto()?',options:['rootUrl','origin','baseURL','hostUrl'],answer:2,explanation:'The `baseURL` property in the `use` object of playwright.config.ts sets a base URL. When set, `page.goto("/login")` automatically prepends the baseURL, keeping tests free of hard-coded hostnames.'},
{id:4403,topic:'playwright',difficulty:'intermediate',question:'What does the `projects` array in playwright.config.ts allow you to do?',options:['Define separate test environments running different browser/device configs','List npm packages required by tests','Specify test file patterns to include','Configure CI pipeline stages'],answer:0,explanation:'The `projects` array lets you run the same test suite against multiple configurations — different browsers, devices, or settings — in a single `npx playwright test` run. Each project can override global `use` options.'},
{id:4404,topic:'playwright',difficulty:'intermediate',question:'What does the `retries` option in playwright.config.ts control?',options:['Number of times a browser is launched','Number of times a failing test is automatically re-run','Number of parallel workers','Number of screenshots taken on failure'],answer:1,explanation:'`retries` defines how many times Playwright will automatically retry a failing test before marking it as failed. Setting `retries: 2` means a test can fail up to two extra times before the suite reports it as a failure.'},
{id:4405,topic:'playwright',difficulty:'intermediate',question:'Which Playwright locator finds an element by its visible text content?',options:['page.getByRole()','page.getByLabel()','page.getByText()','page.getByTitle()'],answer:2,explanation:'`page.getByText(text)` locates elements whose visible text matches the provided string or regex. By default it performs a substring match; passing `{ exact: true }` requires an exact full-string match.'},
{id:4406,topic:'playwright',difficulty:'intermediate',question:'What does `page.getByLabel("Email")` match?',options:['Any element with id="Email"','An input associated with a label whose text is "Email"','A button with text "Email"','An element with aria-label="Email"'],answer:1,explanation:'`getByLabel()` finds form controls associated with a `<label>` element whose text matches the argument, including via `for`/`id` pairing, `aria-labelledby`, or wrapping. It is the recommended way to locate form fields by their visible label.'},
{id:4407,topic:'playwright',difficulty:'intermediate',question:'Which locator method is used to find elements by their `data-testid` attribute?',options:['page.getByAttribute()','page.getByTestId()','page.getByData()','page.getBySelector()'],answer:1,explanation:'`page.getByTestId(testId)` finds elements whose `data-testid` attribute matches the given value. The attribute name is configurable via `testIdAttribute` in playwright.config.ts, defaulting to `data-testid`.'},
{id:4408,topic:'playwright',difficulty:'intermediate',question:'How do you locate the third item in a list using Playwright locator chaining?',options:["locator.item(3)",'locator.nth(2)','locator.get(3)','locator.index(2)'],answer:1,explanation:'`locator.nth(index)` returns a locator for the element at the given zero-based index. So `.nth(2)` returns the third match. `.first()` and `.last()` are convenient shorthands for index 0 and the last element respectively.'},
{id:4409,topic:'playwright',difficulty:'intermediate',question:'What does `locator.filter({ hasText: "Submit" })` do?',options:['Creates a new locator matching only elements that contain the text "Submit"','Waits for the element to have text "Submit"','Asserts that all matched elements have the text "Submit"','Filters the DOM tree globally'],answer:0,explanation:'`locator.filter()` narrows an existing locator to only elements that satisfy additional conditions such as `hasText`, `has`, or `hasNot`. It is useful for disambiguating when multiple elements match the base selector.'},
{id:4410,topic:'playwright',difficulty:'intermediate',question:'What does "auto-waiting" mean in Playwright?',options:['Playwright automatically adds sleep() calls between actions','Before acting on an element, Playwright waits for it to meet actionability conditions','Playwright retries the entire test on timeout','Playwright waits a fixed 2-second delay before each step'],answer:1,explanation:'Playwright auto-waiting means that before performing any action (click, fill, etc.), it waits for the target element to become attached to the DOM, visible, stable (not animating), and enabled. This eliminates the need for explicit waits in most cases.'},
{id:4411,topic:'playwright',difficulty:'intermediate',question:'Which actionability condition requires an element to not be animating or transitioning before Playwright acts on it?',options:['Enabled','Attached','Stable','Visible'],answer:2,explanation:'"Stable" is the actionability condition that ensures the element\'s bounding box has stopped moving. Playwright waits for the element to be stable before clicking to avoid accidentally clicking during CSS animations or transitions.'},
{id:4412,topic:'playwright',difficulty:'intermediate',question:'Which Playwright assertion checks that a locator resolves to exactly N elements?',options:['expect(locator).toHaveLength(N)','expect(locator).toHaveCount(N)','expect(locator).countToBe(N)','expect(locator).toBe(N)'],answer:1,explanation:'`expect(locator).toHaveCount(N)` is a web-first assertion that waits until the number of elements matching the locator equals N. It retries until the count matches or the timeout expires.'},
{id:4413,topic:'playwright',difficulty:'intermediate',question:'What does `expect(locator).toHaveValue("john@example.com")` assert?',options:['The element text content is "john@example.com"','The input element\'s current value attribute is "john@example.com"','The element\'s placeholder is "john@example.com"','The element has a data attribute equal to "john@example.com"'],answer:1,explanation:'`toHaveValue()` asserts the current value of an `<input>`, `<textarea>`, or `<select>` element. It uses the `.value` property, not the text content or placeholder, and retries until matching or timing out.'},
{id:4414,topic:'playwright',difficulty:'intermediate',question:'Which assertion verifies the page URL matches an expected value?',options:['expect(page).toHaveTitle()','expect(page).toHaveURL()','expect(page).urlToBe()','expect(page).matchURL()'],answer:1,explanation:'`expect(page).toHaveURL(url)` is a web-first assertion that waits for the page\'s current URL to match the provided string or regex. It is retried automatically until the URL matches or the timeout expires.'},
{id:4415,topic:'playwright',difficulty:'intermediate',question:'Which assertion checks whether a checkbox or radio button is checked?',options:['expect(locator).toBeChecked()','expect(locator).isChecked()','expect(locator).toHaveState("checked")','expect(locator).checked()'],answer:0,explanation:'`expect(locator).toBeChecked()` is the web-first assertion that waits until the checkbox or radio input is in the checked state. It accepts an optional `{ checked: false }` option to assert the unchecked state.'},
{id:4416,topic:'playwright',difficulty:'intermediate',question:'What does `locator.click()` do if the element is covered by another element?',options:['Throws an error immediately','Playwright scrolls to it and clicks anyway','Playwright auto-waits and retries until the element is not covered, then clicks','Playwright force-clicks through the overlay'],answer:2,explanation:'By default, Playwright waits for the element to pass all actionability checks, including not being obscured by another element. If the element remains covered until the timeout, an error is thrown. You can bypass this with `{ force: true }`.'},
{id:4417,topic:'playwright',difficulty:'intermediate',question:'Which Playwright action simulates selecting an option from a `<select>` dropdown?',options:['locator.click() and then locator.fill()','locator.selectOption(value)','locator.choose(value)','locator.pick(value)'],answer:1,explanation:'`locator.selectOption()` selects one or more options in a `<select>` element. You can select by value, label, or index. It triggers the `change` event on the element just like a user interaction.'},
{id:4418,topic:'playwright',difficulty:'intermediate',question:'What is the purpose of `page.route(url, handler)` in Playwright?',options:['Navigates to a URL with middleware','Intercepts network requests matching the URL pattern and lets you fulfill, modify, or abort them','Registers a service worker route','Creates a new page for the given URL'],answer:1,explanation:'`page.route()` registers a network interception handler. When a request URL matches the pattern, the handler is called with a Route object. You can then call `route.fulfill()`, `route.continue()`, or `route.abort()` to control the response.'},
{id:4419,topic:'playwright',difficulty:'intermediate',question:'What does `route.fulfill({ body: JSON.stringify(data) })` do?',options:['Forwards the request to the real server with the body replaced','Responds to the intercepted request with a mocked response body','Aborts the request with an error body','Delays the request and attaches body data'],answer:1,explanation:'`route.fulfill()` responds to an intercepted network request with a synthetic response. This lets tests mock API responses without hitting a real server, enabling reliable and fast test execution independent of backend state.'},
{id:4420,topic:'playwright',difficulty:'intermediate',question:'Which method aborts an intercepted network request in Playwright?',options:['route.cancel()','route.drop()','route.abort()','route.block()'],answer:2,explanation:'`route.abort()` cancels an intercepted request, causing the browser to receive a network error for that request. It optionally accepts an error code string like `"failed"` or `"timedout"` to control the type of error reported.'},
{id:4421,topic:'playwright',difficulty:'intermediate',question:'How do you record video of a test in Playwright?',options:["Set `video: 'on'` in the `use` section of playwright.config.ts",'Call page.record() at the start of each test','Pass --video flag only to the CLI without config changes','Video recording requires a paid Playwright license'],answer:0,explanation:'Setting `video: "on"` (or `"retain-on-failure"`, `"on-first-retry"`) in the `use` block of playwright.config.ts enables video recording. Videos are saved per test and can be accessed via `testInfo.attachments` or in the HTML report.'},
{id:4422,topic:'playwright',difficulty:'intermediate',question:'What does `page.getByAltText("Company Logo")` target?',options:['An element with title="Company Logo"','An img element whose alt attribute is "Company Logo"','A button with aria-label="Company Logo"','Any element with text "Company Logo"'],answer:1,explanation:'`getByAltText()` locates elements by their `alt` attribute, which is commonly used on `<img>` tags. It is particularly useful for asserting that images are rendered correctly and have meaningful alternative text.'},
{id:4423,topic:'playwright',difficulty:'intermediate',question:'What does `page.getByTitle("Close dialog")` match?',options:['An element with aria-label="Close dialog"','An element with a tooltip or title attribute equal to "Close dialog"','A page whose `<title>` tag is "Close dialog"','An element with id="Close dialog"'],answer:1,explanation:'`getByTitle()` locates elements whose HTML `title` attribute matches the given string. The `title` attribute typically shows as a tooltip on hover and is used for accessibility supplementary information.'},
{id:4424,topic:'playwright',difficulty:'intermediate',question:'What is the purpose of `locator.and(otherLocator)` in Playwright?',options:['Performs a logical OR between two locators','Returns elements matched by both locators simultaneously (intersection)','Waits for both locators to be visible','Chains two click actions together'],answer:1,explanation:'`locator.and(otherLocator)` returns a new locator that matches elements satisfying BOTH the original locator and the additional locator. This is useful for narrowing matches, for example finding a button that is both visible and has a specific text.'},
{id:4425,topic:'playwright',difficulty:'advanced',question:'When Playwright checks the "attached" actionability condition, what does it verify?',options:['The element has a non-zero bounding box','The element is present in the document DOM (not detached)','The element is visible in the viewport','The element has no pointer-events:none CSS property'],answer:1,explanation:'"Attached" means the element is part of the active document\'s DOM tree. A detached element is one that has been removed from the DOM or was created programmatically but never inserted. Playwright checks this before performing any action.'},
{id:4426,topic:'playwright',difficulty:'advanced',question:'How does Playwright\'s locator differ from Playwright\'s older ElementHandle API?',options:['Locators are resolved lazily at action time and retry automatically; ElementHandles are resolved eagerly and can become stale','ElementHandles are faster than locators','Locators only work with CSS selectors','ElementHandles support more actions than locators'],answer:0,explanation:'Locators are lazy — they describe how to find an element but do not resolve until an action is performed. This makes them resilient to re-renders. ElementHandles resolve immediately and can become stale if the DOM changes, similar to Selenium\'s stale element reference problem.'},
{id:4427,topic:'playwright',difficulty:'advanced',question:'What happens when you call `page.screenshot()` on an element handle — `elementHandle.screenshot()`?',options:['It captures the entire page','It captures only the bounding box of the specific element','It throws because ElementHandle does not support screenshot','It captures the visible viewport cropped to the element'],answer:1,explanation:'`elementHandle.screenshot()` captures a screenshot cropped to the element\'s bounding box. This is useful for visual regression testing of individual components without capturing the rest of the page.'},
{id:4428,topic:'playwright',difficulty:'advanced',question:'What is the correct way to perform a CSS selector query using Playwright\'s locator API?',options:["page.locator('css=button.primary')",'page.locator("button.primary")','page.querySelector("button.primary")','page.find("css:button.primary")'],answer:1,explanation:'`page.locator("button.primary")` uses a CSS selector directly. Playwright\'s locator() method accepts CSS selectors, XPath (when prefixed with `xpath=`), text, role, and other engine strings. Plain strings without a prefix are treated as CSS selectors.'},
{id:4429,topic:'playwright',difficulty:'advanced',question:'How do you write an XPath locator in Playwright?',options:["page.locator('xpath=//button[@type=\"submit\"]')",'page.xpath("//button[@type=\'submit\']")','page.locator({ xpath: "//button" })','page.getByXPath("//button")'],answer:0,explanation:'XPath selectors in Playwright use the `xpath=` prefix inside `page.locator()`. For example: `page.locator(\'xpath=//button[@type="submit"]\')`. Playwright supports the full XPath 1.0 specification.'},
{id:4430,topic:'playwright',difficulty:'advanced',question:'What does `page.getByPlaceholder("Search products")` locate?',options:['An element with name="Search products"','An input or textarea whose placeholder attribute matches "Search products"','A label element with the text "Search products"','An element with aria-placeholder="Search products"'],answer:1,explanation:'`getByPlaceholder()` targets `<input>` and `<textarea>` elements by their `placeholder` attribute. It is useful for locating search boxes or form fields that use placeholder text instead of visible labels.'},
{id:4431,topic:'playwright',difficulty:'intermediate',question:'What does `locator.first()` return?',options:['The first element in the DOM','A locator that targets only the first matching element','The text of the first match','A boolean indicating whether any match exists'],answer:1,explanation:'`locator.first()` is shorthand for `locator.nth(0)`. It returns a new locator scoped to the first element in the matching set. It does not evaluate immediately but resolves lazily when an action is performed.'},
{id:4432,topic:'playwright',difficulty:'intermediate',question:'What does `locator.last()` return?',options:['The last character of the element text','A locator targeting the last matching element','The index of the last element','Throws if there is more than one match'],answer:1,explanation:'`locator.last()` returns a locator scoped to the last element in the matching set. It is equivalent to calling `locator.nth(-1)` in some frameworks, but Playwright provides it as an explicit convenience method.'},
{id:4433,topic:'playwright',difficulty:'intermediate',question:'Which Playwright action uploads a file to an `<input type="file">` element?',options:['locator.uploadFile()','locator.setInputFiles()','locator.attachFile()','locator.sendFile()'],answer:1,explanation:'`locator.setInputFiles(filePath)` sets the files to be uploaded via an `<input type="file">` element. It accepts a path string, array of paths, or a `{ name, mimeType, buffer }` object for in-memory files.'},
{id:4434,topic:'playwright',difficulty:'intermediate',question:'What is the difference between `locator.type()` and `locator.fill()` in Playwright?',options:['There is no difference','fill() types character by character; type() sets value at once','type() dispatches individual keypress events per character; fill() sets the value atomically','fill() works only on textareas; type() works on all inputs'],answer:2,explanation:'`locator.type()` simulates typing by dispatching individual `keydown`, `keypress`, `input`, and `keyup` events for each character, mimicking real keyboard input. `locator.fill()` clears and sets the value in a single operation, which is faster but skips per-keystroke events.'},
{id:4435,topic:'playwright',difficulty:'intermediate',question:'What does `locator.press("Enter")` do?',options:['Presses Enter on the keyboard for the focused element','Clicks the element and then presses Enter','Fills the input with the text "Enter"','Simulates a form submit button click'],answer:0,explanation:'`locator.press(key)` focuses the element and dispatches the given key event. `"Enter"` triggers keydown, keypress, and keyup for the Enter key. It is commonly used to submit forms or trigger actions after filling an input.'},
{id:4436,topic:'playwright',difficulty:'intermediate',question:'What does `locator.hover()` do in Playwright?',options:['Highlights the element with a yellow border','Moves the mouse pointer over the element, triggering hover/mouseover events','Waits for a tooltip to appear','Asserts the element has a hover CSS state'],answer:1,explanation:'`locator.hover()` moves the simulated mouse to the center of the element and triggers `mouseover`, `mouseenter`, and related events. It is useful for testing dropdown menus, tooltips, and other hover-triggered UI behaviors.'},
{id:4437,topic:'playwright',difficulty:'intermediate',question:'How do you double-click an element using Playwright?',options:['locator.click({ count: 2 })','locator.dblclick()','locator.doubleClick()','locator.click() called twice in sequence'],answer:1,explanation:'`locator.dblclick()` performs a double-click action on the element. It dispatches two `click` events followed by a `dblclick` event, matching real browser double-click behavior. `locator.click({ count: 2 })` also achieves double-click.'},
{id:4438,topic:'playwright',difficulty:'intermediate',question:'What does `expect(locator).toHaveAttribute("href", "/home")` assert?',options:['The element\'s text content is "/home"','The element has an href attribute with the value "/home"','The element navigates to "/home" on click','The element has a CSS class of "/home"'],answer:1,explanation:'`toHaveAttribute(name, value)` asserts that the matched element has the specified HTML attribute with the specified value. It retries automatically and supports regex for the value argument.'},
{id:4439,topic:'playwright',difficulty:'intermediate',question:'Which Playwright assertion checks that an element is not disabled?',options:['expect(locator).toBeEnabled()','expect(locator).notDisabled()','expect(locator).isEnabled()','expect(locator).toBeClickable()'],answer:0,explanation:'`expect(locator).toBeEnabled()` waits and asserts that the form element (input, button, select, etc.) is not disabled. It uses the element\'s `disabled` property. Use `toBeDisabled()` to assert the opposite.'},
{id:4440,topic:'playwright',difficulty:'intermediate',question:'How does `expect(locator).toContainText("Welcome")` differ from `toHaveText("Welcome")`?',options:['toContainText checks a substring match; toHaveText requires an exact full-text match by default','They are identical','toHaveText checks a substring; toContainText requires an exact match','toContainText works on lists; toHaveText works on single elements'],answer:0,explanation:'`toContainText()` passes if the element\'s text contains the given substring. `toHaveText()` by default requires the full text to match (or match the full text when using regex). Both support arrays for checking multiple elements.'},
{id:4441,topic:'playwright',difficulty:'advanced',question:'What is the purpose of `storageState` in a BrowserContext?',options:['Defines how much memory the browser context can use','Saves or loads cookies and localStorage state to/from a JSON file for session reuse','Configures the storage quota for IndexedDB','Sets the max number of items in sessionStorage'],answer:1,explanation:'`storageState` allows saving authenticated session data (cookies, localStorage, sessionStorage) to a file and reusing it across tests. This avoids logging in repeatedly and is the recommended way to handle authentication in Playwright test suites.'},
{id:4442,topic:'playwright',difficulty:'advanced',question:'What does `browser.newContext({ storageState: "auth.json" })` accomplish?',options:['Creates a new context pre-loaded with saved cookies and localStorage from auth.json','Reads credentials from auth.json to auto-fill login forms','Mounts auth.json as a service worker','Imports browser extensions defined in auth.json'],answer:0,explanation:'Passing `storageState` to `browser.newContext()` pre-loads the new context with cookies and web storage saved in the JSON file. This enables tests to start in an already-authenticated state without repeating the login flow.'},
{id:4443,topic:'playwright',difficulty:'advanced',question:'What does `page.evaluate(() => document.title)` return in Playwright?',options:['A Playwright Locator for the title element','A Promise resolving to the string value of the document title','An ElementHandle for the <title> tag','A screenshot of the page title'],answer:1,explanation:'`page.evaluate(fn)` executes the provided function in the browser page context and returns the serialized result as a Promise. It is used to access browser-side JavaScript values, DOM properties, or custom scripts from the test.'},
{id:4444,topic:'playwright',difficulty:'advanced',question:'How do you pass a value from Node.js test code into `page.evaluate()`?',options:['Use a global variable','Pass a second argument to page.evaluate(): page.evaluate((x) => x * 2, value)','Write the value into a DOM attribute first','Use page.exposeFunction()'],answer:1,explanation:'`page.evaluate(fn, arg)` accepts a second argument that is serialized and passed as the first parameter of `fn` inside the browser. The argument must be JSON-serializable (or an ElementHandle/JSHandle).'},
{id:4445,topic:'playwright',difficulty:'intermediate',question:'What is `BrowserContext` used for in Playwright test parallelism?',options:['Sharing state between all parallel workers','Providing full isolation between tests running in parallel by maintaining separate cookies and storage','Locking browser instances during parallel runs','Synchronizing test steps across workers'],answer:1,explanation:'Each BrowserContext is fully isolated — separate cookies, localStorage, and HTTP sessions. Playwright creates a new context per test by default, enabling true parallel execution without state leakage between tests.'},
{id:4446,topic:'playwright',difficulty:'intermediate',question:'Which Playwright config option controls how many browser processes run in parallel?',options:['parallel','threads','workers','concurrency'],answer:2,explanation:'The `workers` option in playwright.config.ts (or `--workers` CLI flag) sets the number of parallel worker processes. Each worker runs in a separate Node.js process and can run one test at a time by default.'},
{id:4447,topic:'playwright',difficulty:'intermediate',question:'What is the `fullyParallel` option in playwright.config.ts?',options:['Forces all tests to run sequentially with full isolation','Runs each individual test in parallel rather than just test files in parallel','Enables parallel assertions within a single test','Doubles the number of worker processes'],answer:1,explanation:'When `fullyParallel: true` is set, Playwright runs individual tests within the same file in parallel across workers, not just separate files. Without it, tests within a single file run sequentially in the same worker.'},
{id:4448,topic:'playwright',difficulty:'intermediate',question:'What does `expect(locator).toBeVisible()` assert?',options:['The element exists in the DOM','The element is in the viewport','The element is visible — present in DOM, has non-zero dimensions, and is not hidden via CSS','The element has a non-transparent background'],answer:2,explanation:'`toBeVisible()` asserts that the element is attached to the DOM, has non-zero bounding box dimensions, and is not hidden by CSS properties like `display:none`, `visibility:hidden`, or `opacity:0`. It retries until the condition is true.'},
{id:4449,topic:'playwright',difficulty:'intermediate',question:'How do you check a checkbox using Playwright if it is currently unchecked?',options:['locator.click()','locator.check()','locator.toggle()','locator.setValue(true)'],answer:1,explanation:'`locator.check()` ensures a checkbox or radio button is checked. Unlike `click()`, it first verifies the current state and only performs the click if the element is currently unchecked, making it idempotent.'},
{id:4450,topic:'playwright',difficulty:'intermediate',question:'What does `locator.uncheck()` do if the checkbox is already unchecked?',options:['Throws an error','Does nothing (idempotent — it verifies the state and skips the click)','Clicks the checkbox causing it to become checked','Throws a warning but continues'],answer:1,explanation:'`locator.uncheck()` ensures the element is unchecked. It first reads the current state; if already unchecked, it takes no action. This idempotent behavior makes tests more robust than using `click()` blindly.'},
{id:4451,topic:'playwright',difficulty:'intermediate',question:'What does `locator.focus()` do?',options:['Scrolls the element into view','Gives keyboard focus to the element','Takes a screenshot of the focused element','Asserts the element is focusable'],answer:1,explanation:'`locator.focus()` moves keyboard focus to the element by triggering the `focus` event. This is useful for testing keyboard-driven interactions or for ensuring the correct element receives subsequent keyboard input.'},
{id:4452,topic:'playwright',difficulty:'intermediate',question:'What does `locator.blur()` do in Playwright?',options:['Takes a blurred/out-of-focus screenshot','Removes keyboard focus from the element, triggering the blur event','Waits for the element to become invisible','Clears the value of an input'],answer:1,explanation:'`locator.blur()` removes focus from the element, dispatching `blur` and `focusout` events. It is used to trigger validation that fires on focus loss, such as inline form field error messages.'},
{id:4453,topic:'playwright',difficulty:'intermediate',question:'What does `locator.tap()` do?',options:['Listens for tap events on the element','Simulates a touch tap on the element for mobile testing','Double-taps the element','Performs a right-click on the element'],answer:1,explanation:'`locator.tap()` dispatches a touch `tap` event on the element. It is used when testing mobile web views or when the application has different behavior for touch events versus mouse clicks. Requires the browser context to have touch emulation enabled.'},
{id:4454,topic:'playwright',difficulty:'advanced',question:'In Playwright, what is the difference between `page.evaluate()` and `page.evaluateHandle()`?',options:['They are identical','evaluate() returns a serialized value; evaluateHandle() returns a JSHandle referencing the browser-side object','evaluateHandle() runs in Node.js; evaluate() runs in the browser','evaluate() is async; evaluateHandle() is synchronous'],answer:1,explanation:'`page.evaluate()` serializes and transfers the result from browser to Node.js (JSON-compatible values only). `page.evaluateHandle()` returns a JSHandle — a reference to the browser-side object — without transferring it. JSHandles are useful for passing complex objects back to further browser-side calls.'},
{id:4455,topic:'playwright',difficulty:'advanced',question:'What happens to a JSHandle created by `page.evaluateHandle()` if you do not dispose of it?',options:['It is automatically garbage collected after the page navigates','It holds a reference in the browser process and may cause memory leaks if not disposed','It is cleaned up after each test automatically','It converts to a serialized value after 30 seconds'],answer:1,explanation:'JSHandles maintain a reference to a JavaScript object in the browser context. If you create many without calling `jsHandle.dispose()`, the objects cannot be garbage collected in the browser, potentially causing memory leaks in long test suites.'},
{id:4456,topic:'playwright',difficulty:'advanced',question:'What is the purpose of `page.waitForSelector()` and when should you prefer locators instead?',options:['waitForSelector() is the modern API; locators are legacy','waitForSelector() returns an ElementHandle and is considered lower-level; prefer locators with built-in auto-waiting for most use cases','They are interchangeable with no practical difference','waitForSelector() is only available in Selenium compatibility mode'],answer:1,explanation:'`page.waitForSelector()` returns an ElementHandle and predates the locator API. While it still works, Playwright recommends using locators with web-first assertions instead, as locators automatically retry, are more composable, and avoid stale element issues.'},
{id:4457,topic:'playwright',difficulty:'intermediate',question:'How do you intercept and modify request headers using `page.route()`?',options:["Call route.modifyHeaders({})",'Call route.continue({ headers: { ...request.headers(), "x-custom": "value" } })','Use page.setExtraHTTPHeaders() inside the route handler','Headers cannot be modified with page.route()'],answer:1,explanation:'`route.continue()` lets you forward the request with modifications. Passing a `headers` object merges or overrides headers. `route.request().headers()` retrieves the original headers so you can spread them and add or override specific values.'},
{id:4458,topic:'playwright',difficulty:'intermediate',question:'Which method saves an element\'s screenshot to a file in Playwright?',options:["page.screenshot({ path: 'shot.png' })",'locator.screenshot({ path: "element.png" })','locator.capture("element.png")','elementHandle.save("element.png")'],answer:1,explanation:'`locator.screenshot({ path: "element.png" })` takes a screenshot of the specific element\'s bounding box and saves it to the specified file path. If no `path` is given, the PNG buffer is returned without saving.'},
{id:4459,topic:'playwright',difficulty:'intermediate',question:'What video format does Playwright use for recorded test videos?',options:['MP4 (H.264)','WebM','AVI','GIF'],answer:1,explanation:'Playwright records test videos in WebM format using the VP8 codec. The video files are saved in a directory specified by `outputDir` or within the test results folder, and are accessible through the HTML report.'},
{id:4460,topic:'playwright',difficulty:'advanced',question:'What does setting `video: "retain-on-failure"` do in playwright.config.ts?',options:['Records video only on the first test run','Records video for all tests but only keeps files for failing tests','Records only the last 10 seconds before failure','Disables video but saves a crash dump on failure'],answer:1,explanation:'`"retain-on-failure"` records video for every test but deletes the video files of passing tests at the end of the run. This reduces disk usage while still providing video evidence for debugging failures.'},
{id:4461,topic:'playwright',difficulty:'intermediate',question:'What does `page.route("**/*.png", route => route.abort())` accomplish?',options:['Downloads all PNG images to disk','Blocks all PNG image requests from loading','Replaces all PNG images with a placeholder','Logs all PNG requests to the console'],answer:1,explanation:'This route intercepts all requests whose URL ends in `.png` and aborts them, causing the browser to not load those images. This technique is used to speed up tests that do not need to verify visual content.'},
{id:4462,topic:'playwright',difficulty:'intermediate',question:'Which Playwright method navigates back in browser history?',options:['page.back()','page.historyBack()','page.navigate(-1)','page.goBack()'],answer:3,explanation:'`page.goBack()` navigates the page to the previous history entry, equivalent to clicking the browser\'s back button. It returns a Response object or null if navigation was unsuccessful.'},
{id:4463,topic:'playwright',difficulty:'intermediate',question:'How do you reload the current page in Playwright?',options:['page.refresh()','page.reload()','page.navigate(page.url())','page.reset()'],answer:1,explanation:'`page.reload()` reloads the current page. It accepts options like `{ waitUntil: "networkidle" }` to control when it resolves. It is equivalent to pressing F5 in the browser.'},
{id:4464,topic:'playwright',difficulty:'intermediate',question:'What does `page.waitForURL("/dashboard")` do?',options:['Waits for a network request to /dashboard','Navigates to /dashboard','Waits until the page URL matches "/dashboard"','Asserts the URL and fails immediately if it does not match'],answer:2,explanation:'`page.waitForURL()` waits until the page\'s URL matches the provided string, glob, or regex pattern. It is often used after an action that triggers navigation to confirm the navigation occurred before proceeding.'},
{id:4465,topic:'playwright',difficulty:'intermediate',question:'Which assertion in Playwright verifies that the page `<title>` matches a value?',options:['expect(page).toHaveURL()','expect(page).toHaveTitle()','expect(page).titleToBe()','expect(page).toContainTitle()'],answer:1,explanation:'`expect(page).toHaveTitle(title)` asserts the document title matches the given string or regex. It is a web-first assertion that retries until the title matches or the timeout is reached.'},
{id:4466,topic:'playwright',difficulty:'intermediate',question:'What does `page.waitForLoadState("networkidle")` wait for?',options:['The DOM to be interactive','The first paint to occur','No more than 0 network connections for at least 500ms','All JavaScript to finish executing'],answer:2,explanation:'`"networkidle"` waits until there are no more than 0 in-flight network connections for at least 500 milliseconds. Note that Playwright docs caution against relying on networkidle as it can be slow and flaky for dynamic applications.'},
{id:4467,topic:'playwright',difficulty:'intermediate',question:'What is a Playwright "fixture" in the context of @playwright/test?',options:['A static HTML file used as a test baseline','A value or object set up for a test and torn down after, provided via dependency injection to test functions','A CSS snapshot file used for visual comparison','A database seed file loaded before tests'],answer:1,explanation:'Fixtures in Playwright Test are set up before a test and automatically cleaned up after. They are declared as parameters in test functions and managed by the test runner, providing dependency injection for common objects like `page`, `browser`, and `context`.'},
{id:4468,topic:'playwright',difficulty:'intermediate',question:'Which built-in Playwright fixture provides the current browser\'s name ("chromium", "firefox", or "webkit") inside a test?',options:['browserType','browser.name()','browserName','currentBrowser'],answer:2,explanation:'The `browserName` fixture is a built-in string fixture provided by `@playwright/test`. Its value is one of `"chromium"`, `"firefox"`, or `"webkit"` and can be used in tests to skip or adjust behavior for specific browsers.'},
{id:4469,topic:'playwright',difficulty:'intermediate',question:'What does `test.use({ viewport: { width: 375, height: 812 } })` do in a test file?',options:['Creates a new test for mobile screen size','Overrides the viewport for all tests in the current describe block or file','Sets the global viewport for all projects','Skips tests if the screen is larger than 375px'],answer:1,explanation:'`test.use()` overrides specific `use` options for all tests within the current scope (describe block or entire file). Setting `viewport` here changes the browser window size for those tests, useful for mobile responsiveness testing.'},
{id:4470,topic:'playwright',difficulty:'intermediate',question:'What is the correct way to skip a test in Playwright conditionally based on browser?',options:["test.skip(browserName === 'firefox', 'Not supported in Firefox')",'test.ignore("firefox")','test.only("chromium")','test.exclude({ browser: "firefox" })'],answer:0,explanation:'`test.skip(condition, reason)` skips the test if the condition is true. When used inside the test body with `browserName`, it skips only on that browser. When used at the top level with `test.skip()` (no args), it skips unconditionally.'},
{id:4471,topic:'playwright',difficulty:'intermediate',question:'Which Playwright method waits for a specific network request to complete?',options:['page.waitForNetworkIdle()','page.waitForRequest()','page.waitForResponse()','page.monitorRequest()'],answer:2,explanation:'`page.waitForResponse(urlOrPredicate)` waits for a network response matching the given URL pattern or predicate function. It returns the matching Response object. `page.waitForRequest()` waits for the request rather than the response.'},
{id:4472,topic:'playwright',difficulty:'advanced',question:'What does `page.waitForEvent("popup")` return?',options:['A boolean indicating a popup occurred','A new Page object representing the popup window','A string with the popup URL','An ElementHandle for the popup trigger'],answer:1,explanation:'`page.waitForEvent("popup")` returns a Promise that resolves to a new `Page` object when a popup window (opened via `window.open()`) is created. You can then interact with the popup page using the same Playwright Page API.'},
{id:4473,topic:'playwright',difficulty:'advanced',question:'How do you handle a new tab opened by a link click in Playwright?',options:['Use page.waitForNavigation() after the click','Use a Promise.all combining the click and page.waitForEvent("popup") to get the new page','Playwright automatically redirects new tabs to the current page','Use browser.pages() after the click'],answer:1,explanation:'When a link opens a new tab, you combine the click with `context.waitForEvent("page")` (or `page.waitForEvent("popup")` for window.open). Using `Promise.all` ensures you capture the new page event without race conditions.'},
{id:4474,topic:'playwright',difficulty:'advanced',question:'What is the purpose of Playwright\'s `expect.configure({ timeout: 10000 })`?',options:['Sets the default timeout for all assertions in the test file','Configures a one-time timeout for the next assertion only','Sets the global action timeout','Replaces the playwright.config.ts timeout setting'],answer:0,explanation:'`expect.configure()` returns a new expect instance with customized defaults. Setting `timeout` adjusts how long assertions wait before failing for all assertions made through that configured instance, useful for setting file-level or custom assertion timeouts.'},
{id:4475,topic:'playwright',difficulty:'advanced',question:'What is Playwright\'s `APIRequestContext` used for?',options:['Intercepting API calls from the browser','Making HTTP requests directly from the test process for API testing','Configuring CORS for the browser context','Creating mock API servers'],answer:1,explanation:'`APIRequestContext` (accessible as the `request` fixture) allows making HTTP requests (GET, POST, PUT, DELETE, etc.) directly from the test code without a browser. It shares authentication state with the browser context by default, making it ideal for API testing or seeding data.'},
{id:4476,topic:'playwright',difficulty:'advanced',question:'How is `request.post()` used in Playwright API testing?',options:["request.post(url, { data: body }) — sends a POST request and returns a response","request.post(url) — performs a form submit","request.post(url, { body }) — only works for JSON",'It is not available; use page.evaluate(fetch(...)) instead'],answer:0,explanation:'`request.post(url, { data: body })` sends an HTTP POST request. The `data` option can be an object (serialized as JSON), a string, or a Buffer. The returned `APIResponse` includes status, headers, and body parsing methods.'},
{id:4477,topic:'playwright',difficulty:'advanced',question:'What does `response.ok()` return in Playwright\'s APIResponse?',options:['True if the response body is not empty','True if the HTTP status code is in the 200–299 range','True if the request did not time out','True if response headers include Content-Type: application/json'],answer:1,explanation:'`response.ok()` returns `true` when the response HTTP status is between 200 and 299 inclusive. It is a convenience method equivalent to checking `response.status() >= 200 && response.status() <= 299`.'},
{id:4478,topic:'playwright',difficulty:'intermediate',question:'What does `page.keyboard.press("Tab")` do?',options:['Inserts a tab character into the focused input','Moves keyboard focus to the next focusable element','Opens the browser developer tools','Simulates clicking the Tab key with keydown, keypress, and keyup events dispatched'],answer:3,explanation:'`page.keyboard.press("Tab")` dispatches keydown, keypress (if applicable), and keyup events for the Tab key on the currently focused element, moving focus to the next element in the tab order just as a real user would.'},
{id:4479,topic:'playwright',difficulty:'intermediate',question:'What does `page.keyboard.type("Hello World")` do differently from `locator.fill()`?',options:['It does not focus the element first','It types each character with real key events; fill() sets value atomically','It only works for single characters','There is no difference'],answer:1,explanation:'`page.keyboard.type()` dispatches individual keydown, keypress, input, and keyup events for every character, simulating real typing. This is useful when testing keyup/keydown event handlers, autocomplete, or applications that respond to individual keystrokes.'},
{id:4480,topic:'playwright',difficulty:'intermediate',question:'What does `page.keyboard.down("Shift")` do?',options:['Types the Shift key character','Presses and holds the Shift key without releasing it','Scrolls the page down by one page','Moves focus down to the next element'],answer:1,explanation:'`page.keyboard.down(key)` dispatches a keydown event for the key and keeps it held. Subsequent `keyboard.press()` or `keyboard.type()` calls will have the Shift modifier active. Use `page.keyboard.up("Shift")` to release.'},
{id:4481,topic:'playwright',difficulty:'intermediate',question:'How do you simulate pressing Ctrl+A (select all) in Playwright?',options:["page.keyboard.press('Control+A')",'page.keyboard.shortcut("Ctrl", "A")','page.click({ shortcut: "Ctrl+A" })','page.evaluate(() => document.execCommand("selectAll"))'],answer:0,explanation:'`page.keyboard.press("Control+A")` (or `"Meta+A"` on macOS) dispatches the combined keyboard shortcut. The `+` notation in `press()` allows specifying modifier key combinations in a single call.'},
{id:4482,topic:'playwright',difficulty:'intermediate',question:'What does `page.mouse.move(x, y)` do in Playwright?',options:['Clicks the mouse at coordinates (x, y)','Moves the virtual mouse cursor to the given page coordinates','Scrolls the page to position (x, y)','Moves an element to position (x, y) using drag and drop'],answer:1,explanation:'`page.mouse.move(x, y)` moves the simulated mouse cursor to the given absolute page coordinates and dispatches `mousemove` events. It is used for hover testing, drag and drop, and testing mouse-tracking features.'},
{id:4483,topic:'playwright',difficulty:'intermediate',question:'How do you simulate a drag-and-drop action in Playwright?',options:["page.dragAndDrop(source, target)",'page.mouse.move(x1,y1); page.mouse.down(); page.mouse.move(x2,y2); page.mouse.up()','locator.drag(target)','All of the above are valid approaches'],answer:3,explanation:'Playwright supports drag and drop via `page.dragAndDrop(source, target)` for convenience, or manually with `page.mouse.move/down/move/up` for fine-grained control. Both approaches are valid and achieve the same result.'},
{id:4484,topic:'playwright',difficulty:'intermediate',question:'How do you capture a `dialog` (alert, confirm, prompt) in Playwright?',options:["page.on('dialog', dialog => dialog.accept())",'page.waitForAlert()','browser.captureDialog()','page.interceptDialog()'],answer:0,explanation:'Register a `dialog` event handler on the page before triggering the action. The handler receives a `Dialog` object. If no handler is registered, Playwright automatically dismisses dialogs to prevent tests from hanging.'},
{id:4485,topic:'playwright',difficulty:'intermediate',question:'What does `dialog.message()` return in Playwright?',options:['The dialog\'s button labels','The text message displayed in the dialog box','The dialog type (alert/confirm/prompt)','The default value of a prompt dialog'],answer:1,explanation:'`dialog.message()` returns the text displayed inside the dialog box. For alert dialogs this is the alert message; for confirm dialogs the confirmation question; for prompt dialogs the prompt message.'},
{id:4486,topic:'playwright',difficulty:'intermediate',question:'How do you dismiss a confirm dialog in Playwright?',options:['dialog.close()','dialog.dismiss()','dialog.cancel()','dialog.reject()'],answer:1,explanation:'`dialog.dismiss()` clicks the Cancel button (or equivalent) on a confirm or prompt dialog. For alert dialogs, dismiss has the same effect as accept since there is only one button. `dialog.accept()` clicks OK.'},
{id:4487,topic:'playwright',difficulty:'intermediate',question:'How do you provide a value for a `window.prompt()` dialog in Playwright?',options:["dialog.fill('value')",'dialog.accept("value")','dialog.type("value")','dialog.setValue("value")'],answer:1,explanation:'`dialog.accept(promptText)` accepts a prompt dialog and optionally provides the value to enter in the input field. If no argument is given, the prompt\'s default value is submitted.'},
{id:4488,topic:'playwright',difficulty:'advanced',question:'What is the `download` event and how do you get a downloaded file\'s path?',options:["Listen with page.on('download', d => d.path()) — but path() requires awaiting since it resolves asynchronously",'Use page.waitForDownload() which returns the path directly','Use page.waitForEvent("download") and then await download.path() to get the saved file path','Downloads are not supported in Playwright'],answer:2,explanation:'`await page.waitForEvent("download")` returns a `Download` object when a file download starts. `await download.path()` returns the path to the temporary file after it finishes downloading. You can also call `download.saveAs(path)` to copy it elsewhere.'},
{id:4489,topic:'playwright',difficulty:'advanced',question:'What does `download.suggestedFilename()` return?',options:['The MIME type of the downloaded file','The suggested filename from the Content-Disposition header or URL','The full download URL','The size of the downloaded file in bytes'],answer:1,explanation:'`download.suggestedFilename()` returns the filename suggested by the server via the `Content-Disposition: attachment; filename="..."` header, or derived from the URL if the header is absent. It does not include the full path.'},
{id:4490,topic:'playwright',difficulty:'advanced',question:'How do you capture browser console messages in a Playwright test?',options:["page.on('console', msg => console.log(msg.text()))",'page.interceptConsole()','test.captureConsole()','browser.on("console", handler)'],answer:0,explanation:'Register a `console` event listener on the page: `page.on("console", msg => ...)`. The handler receives a `ConsoleMessage` object with `.type()` (log/warn/error) and `.text()` methods. This is useful for asserting log output or detecting unexpected errors.'},
{id:4491,topic:'playwright',difficulty:'advanced',question:'How do you capture uncaught JavaScript exceptions thrown on the page in Playwright?',options:["page.on('pageerror', err => ...)",'page.on("uncaughtException", handler)','browser.on("error", handler)','page.evaluate(() => window.onerror = handler)'],answer:0,explanation:'`page.on("pageerror", error => ...)` fires when an unhandled exception occurs in the page\'s JavaScript. The handler receives an `Error` object. This allows tests to fail on unexpected client-side errors.'},
{id:4492,topic:'playwright',difficulty:'advanced',question:'What does `page.on("requestfailed", request => ...)` help you detect?',options:['Requests blocked by ad-blockers','Network requests that failed to complete (e.g., connection refused, aborted)','Slow requests exceeding a timeout','Requests with non-200 status codes'],answer:1,explanation:'The `requestfailed` event fires when a network request fails to receive a response — for example due to DNS errors, connection refused, or being aborted. It is distinct from receiving an error HTTP status code (e.g., 404 or 500).'},
{id:4493,topic:'playwright',difficulty:'intermediate',question:'What does the `baseURL` option allow when combined with `page.goto("/login")`?',options:['Playwright resolves "/login" against baseURL to produce the full URL','page.goto() ignores baseURL for relative paths','baseURL applies only to API requests','It replaces all hrefs on the page'],answer:0,explanation:'When `baseURL` is configured (e.g., `https://app.example.com`), calling `page.goto("/login")` automatically resolves to `https://app.example.com/login`. This lets tests use relative paths and easily switch environments via config.'},
{id:4494,topic:'playwright',difficulty:'intermediate',question:'What is the purpose of `test.describe.parallel()` in Playwright?',options:['Runs all tests in the describe block in parallel within a single worker','Marks tests as parallelizable across multiple worker processes','Runs describe blocks in a separate browser context','Enables parallel assertions within one test'],answer:0,explanation:'`test.describe.parallel()` runs the tests inside the describe block in parallel within the same group, overriding the default sequential execution within a file. This is a fine-grained alternative to setting `fullyParallel: true` globally.'},
{id:4495,topic:'playwright',difficulty:'intermediate',question:'What does the `shard` CLI option do in Playwright?',options:['Splits test results into multiple HTML report files','Divides the total test suite into N shards and runs only one shard','Enables distributed caching of test results','Creates sub-projects from a single config'],answer:1,explanation:'`--shard=1/3` splits the total set of test files into 3 equal parts and runs only the first part. This enables distributing tests across CI machines. Combine with the `--merge-reports` command to aggregate results.'},
{id:4496,topic:'playwright',difficulty:'intermediate',question:'Which Playwright reporter produces an interactive HTML report that can be opened in a browser?',options:['json','list','html','github'],answer:2,explanation:'The `html` reporter generates a self-contained `playwright-report/index.html` file with an interactive UI showing test results, attachments, screenshots, videos, and traces. Open it with `npx playwright show-report`.'},
{id:4497,topic:'playwright',difficulty:'intermediate',question:'What does `expect.soft()` do in Playwright?',options:['Marks the assertion as expected to fail','Performs the assertion but does not abort the test on failure — collects all soft failures and reports them at the end','Adds a 5-second soft timeout to the assertion','Logs the assertion result without affecting pass/fail status'],answer:1,explanation:'`expect.soft(value)` creates a soft assertion. If it fails, the test continues running instead of stopping immediately. All soft assertion failures are collected and reported together when the test finishes, useful for validating multiple conditions.'},
{id:4498,topic:'playwright',difficulty:'advanced',question:'What is the Playwright Trace Viewer and how do you open a trace?',options:['A live debugging tool running alongside the browser during tests','A CLI command that replays network requests','A web UI that lets you step through test actions, view screenshots, network requests, and console logs from a recorded trace file opened with `npx playwright show-trace trace.zip`','A VS Code extension showing test steps in real time'],answer:2,explanation:'The Playwright Trace Viewer is a web-based tool for post-mortem debugging. Traces are recorded by configuring `trace: "on"` (or `"retain-on-failure"`) and collected as `.zip` files. Open them with `npx playwright show-trace trace.zip` to inspect each action with before/after screenshots and network activity.'},
{id:4499,topic:'playwright',difficulty:'advanced',question:'How do you enable trace recording in playwright.config.ts?',options:["Set `trace: 'on'` in the `use` block",'Pass --trace flag at the CLI','Call test.trace() at the beginning of each test','Traces are always enabled by default'],answer:0,explanation:'Setting `trace: "on"` in the `use` object records a trace for every test. Options include `"on"`, `"off"`, `"retain-on-failure"` (most common for CI), and `"on-first-retry"`. The trace zip includes screenshots, DOM snapshots, and network logs.'},
{id:4500,topic:'playwright',difficulty:'advanced',question:'What information is captured in a Playwright trace file?',options:['Only network requests and responses','Only screenshots at each step','Action logs, before/after DOM snapshots, network requests/responses, console messages, and source location for each step','A video recording and a list of failing assertions only'],answer:2,explanation:'A Playwright trace file captures a rich debugging snapshot including: the list of test actions with timing, DOM snapshots before and after each action, network request/response details, console messages, and the source code location of each test step.'},
]);
